declare(strict_types=1);namespace BSPResearch;require dirname(__DIR__).'/_lib/site.php';security();header('Cache-Control: no-store');header('X-Robots-Tag: noindex');if(!in_array(parse_url($_SERVER['REQUEST_URI']??'',PHP_URL_PATH),['/research/api/','/research/api/index.php'],true)){http_response_code(404);exit('Not found');}
function response($v,int $status=200):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');echo encode($v);exit;}
function emit(array $e):void{echo 'data: '.encode($e)."\n\n";if(ob_get_level()>0)ob_flush();flush();}
$method=$_SERVER['REQUEST_METHOD']??'GET';if(in_array($method,['GET','HEAD'],true))response(catalog()+['transport'=>'JSON or limited AG-UI POST SSE','replay'=>'Submit expected_sha256 alongside plan.']);if($method!=='POST'){header('Allow: GET, HEAD, POST');response(['error'=>'Method not allowed'],405);}try{if(!preg_match('~^application/json(?:\s*;|$)~i',$_SERVER['CONTENT_TYPE']??''))throw new \InvalidArgumentException('Expected application/json.');$d=decode(file_get_contents('php://input',false,null,0,65537));$agent=array_key_exists('state',$d);if($agent){foreach(['threadId','runId'] as $k)if(!is_string($d[$k]??null)||!preg_match('/^[A-Za-z0-9_.:-]{1,128}$/D',$d[$k]))throw new \InvalidArgumentException('Invalid run identifier.');if(!is_array($d['messages']??null)||!array_is_list($d['messages']))throw new \InvalidArgumentException('messages must be an array.');$payload=object($d['state'],'State');}else $payload=$d;keys($payload,['plan','expected_sha256'],'request');$p=normalize(object($payload['plan']??null,'Plan'));$expected=$payload['expected_sha256']??null;if($expected!==null&&(!is_string($expected)||!preg_match('/^[0-9a-f]{64}$/D',$expected)))throw new \InvalidArgumentException('Invalid expected_sha256.');}catch(\InvalidArgumentException|\JsonException $e){response(['error'=>$e->getMessage()],400);}
$envelope=fn($r)=>['result'=>$r,'replay_match'=>$expected===null?null:hash_equals($expected,$r['result_sha256'])];
if(!$agent){try{response($envelope(evaluate($p)));}catch(\Throwable $e){error_log('BSP research calculation: '.$e->getMessage());response(['error'=>'Calculation failed.'],500);}}
header('Content-Type: text/event-stream; charset=utf-8');header('X-Accel-Buffering: no');header('Cache-Control: no-cache, no-store, no-transform');$ids=['threadId'=>$d['threadId'],'runId'=>$d['runId']];emit(['type'=>'RUN_STARTED']+$ids);try{$r=evaluate($p,fn($type,$step)=>emit(['type'=>$type,'stepName'=>$step]));$mid='research-'.bin2hex(random_bytes(8));emit(['type'=>'TEXT_MESSAGE_START','messageId'=>$mid,'role'=>'assistant']);emit(['type'=>'TEXT_MESSAGE_CONTENT','messageId'=>$mid,'delta'=>count($r['runs']).' cases computed; '.count($r['comparisons']).' within-model comparisons. '.$r['interpretation']]);emit(['type'=>'TEXT_MESSAGE_END','messageId'=>$mid]);emit(['type'=>'STATE_SNAPSHOT','snapshot'=>$envelope($r)]);emit(['type'=>'RUN_FINISHED','outcome'=>['type'=>'success']]+$ids);}catch(\Throwable $e){error_log('BSP research run: '.$e->getMessage());emit(['type'=>'RUN_ERROR','message'=>'Calculation failed.','code'=>'CALCULATION_FAILED']);}
